from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    result = {}
    for ip in network.hosts():
        ip_str = str(ip)
        try:
            response = subprocess.run(['ping', '-c', '1', '-W', '1', ip_str], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            result[ip_str] = (response.returncode == 0)
        except subprocess.CalledProcessError:
            raise
    return result

