def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': f'Source folder {src_folder} does not exist', 'failed_files': []}
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception as e:
            return {'success': False, 'message': f'Failed to create destination folder: {str(e)}', 'failed_files': []}
    failed_files = []
    files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    for filename in files:
        src_path = os.path.join(src_folder, filename)
        try:
            result = subprocess.run(['gzip', src_path], capture_output=True, timeout=30)
            if result.returncode != 0:
                failed_files.append(filename)
                continue
            gz_filename = filename + '.gz'
            gz_src_path = src_path + '.gz'
            dst_path = os.path.join(dst_folder, gz_filename)
            shutil.move(gz_src_path, dst_path)
        except Exception:
            failed_files.append(filename)
    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': []}
    else:
        return {'success': False, 'message': f'{len(failed_files)} file(s) failed', 'failed_files': failed_files}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist")
    process = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    try:
        ps_process = psutil.Process(process.pid)
        cpu_usage = 0.0
        memory_usage = 0
        start_time = time.time()
        while process.poll() is None:
            if time.time() - start_time > timeout:
                process.terminate()
                process.wait()
                break
            try:
                cpu_percent = ps_process.cpu_percent(interval=0.1)
                memory_info = ps_process.memory_info()
                cpu_usage += cpu_percent
                memory_usage += memory_info.rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            time.sleep(0.1)
        return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
